import{_ as d,C as o,o as r,c as l,a6 as t,E as a,j as s,a as c}from"./chunks/framework.5dd0l9Wo.js";const z=JSON.parse('{"title":"Insecure Deserialization","description":"Serialized object graphs, magic methods, PHP type juggling, Java gadget chains, Ruby Marshal, and PHAR metadata.","frontmatter":{"title":"Insecure Deserialization","description":"Serialized object graphs, magic methods, PHP type juggling, Java gadget chains, Ruby Marshal, and PHAR metadata."},"headers":[],"relativePath":"deserialization/index.md","filePath":"deserialization/index.md"}'),p={name:"deserialization/index.md"};function u(h,e,g,m,b,_){const i=o("LabGroup"),n=o("TopicComplete");return r(),l("div",null,[e[0]||(e[0]=t('<h1 id="insecure-deserialization" tabindex="-1">Insecure Deserialization <a class="header-anchor" href="#insecure-deserialization" aria-label="Permalink to &quot;Insecure Deserialization&quot;">​</a></h1><p class="wd-section-lede">Deserialization turns a byte stream back into objects. If the stream is attacker-controlled, the attacker controls field values — and in most languages, the act of restoring an object invokes code (magic methods, readObject, callbacks) before your application ever looks at it.</p><div class="wd-callout"><p><strong>The model.</strong> A serializer is a constructor for object graphs. It sets properties, resolves classes, and runs language-level hooks. A &quot;gadget chain&quot; is a path through existing classes whose hooks, when chained, reach a sink such as <code>exec</code>, <code>include</code>, or a file write.</p></div><h2 id="serialized-data-is-a-class-blueprint" tabindex="-1">Serialized data is a class blueprint <a class="header-anchor" href="#serialized-data-is-a-class-blueprint" aria-label="Permalink to &quot;Serialized data is a class blueprint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>Format marker</th><th>Hook on deserialize</th></tr></thead><tbody><tr><td>PHP</td><td><code>O:4:&quot;User&quot;:2:{...}</code></td><td><code>__wakeup</code>, <code>__destruct</code>, <code>__toString</code></td></tr><tr><td>Java</td><td><code>AC ED 00 05</code></td><td><code>readObject</code>, <code>readResolve</code></td></tr><tr><td>Ruby</td><td><code>\\x04\\x08</code></td><td><code>_load</code>, <code>marshal_load</code></td></tr><tr><td>Python</td><td><code>\\x80\\x04</code> (pickle)</td><td><code>__reduce__</code>, <code>__setstate__</code></td></tr><tr><td>.NET</td><td><code>AAEAAAD///</code> (BinaryFormatter)</td><td><code>ISerializable</code>, <code>OnDeserialized</code></td></tr></tbody></table>',5)),a(i,{ids:"deserialization-lab-deserialization-modifying-serialized-objects, deserialization-lab-deserialization-modifying-serialized-data-types"}),e[1]||(e[1]=t(`<details class="details custom-block"><summary>🔬 Under the Hood: PHP serialization arithmetic</summary><p>A PHP serialized object is length-prefixed:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>O:4:&quot;User&quot;:2:{s:5:&quot;admin&quot;;b:0;s:8:&quot;username&quot;;s:6:&quot;wiener&quot;;}</span></span>
<span class="line"><span>│ │  │      │  │          │   │            │</span></span>
<span class="line"><span>│ │  │      │  │          │   │            └─ value bytes</span></span>
<span class="line"><span>│ │  │      │  │          │   └─ string length (must match exactly)</span></span>
<span class="line"><span>│ │  │      │  │          └─ boolean type</span></span>
<span class="line"><span>│ │  │      │  └─ property name length and bytes</span></span>
<span class="line"><span>│ │  └─ property count</span></span>
<span class="line"><span>│ └─ class name length</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Changing <code>b:0</code> to <code>b:1</code> promotes the user. Changing a string value requires updating its length prefix, or the parser fails. This is why &quot;just edit the base64&quot; works only when you respect the grammar — and why type juggling (<code>s:1:&quot;0&quot;</code> vs <code>i:0</code>) is a separate primitive.</p></details><h2 id="magic-methods-and-application-functionality" tabindex="-1">Magic methods and application functionality <a class="header-anchor" href="#magic-methods-and-application-functionality" aria-label="Permalink to &quot;Magic methods and application functionality&quot;">​</a></h2><p>Deserialization hooks can trigger application behaviour without any gadget chain: deleting a file on <code>__destruct</code>, writing a log on <code>__wakeup</code>, or following a path stored in an object property.</p>`,3)),a(i,{ids:"deserialization-lab-deserialization-using-application-functionality-to-exploit-insecure-deserialization, deserialization-lab-deserialization-arbitrary-object-injection-in-php"}),e[2]||(e[2]=s("h2",{id:"gadget-chains",tabindex:"-1"},[c("Gadget chains "),s("a",{class:"header-anchor",href:"#gadget-chains","aria-label":'Permalink to "Gadget chains"'},"​")],-1)),e[3]||(e[3]=s("p",null,"A gadget chain uses classes already present in the application or its dependencies. The attacker does not inject code; they choose an object graph whose destructor or callback eventually calls a dangerous method with attacker-controlled arguments.",-1)),a(i,{ids:"deserialization-lab-deserialization-exploiting-java-deserialization-with-apache-commons, deserialization-lab-deserialization-exploiting-php-deserialization-with-a-pre-built-gadget-chain, deserialization-lab-deserialization-exploiting-ruby-deserialization-using-a-documented-gadget-chain, deserialization-lab-deserialization-developing-a-custom-gadget-chain-for-java-deserialization, deserialization-lab-deserialization-developing-a-custom-gadget-chain-for-php-deserialization"}),e[4]||(e[4]=t('<details class="details custom-block"><summary>🔬 Under the Hood: why <code>ysoserial</code> payloads need the right library</summary><p>A Java gadget chain references concrete classes (<code>InvokerTransformer</code>, <code>TemplatesImpl</code>, <code>BadAttributeValueExpException</code>) and their serialVersionUIDs. If the target&#39;s classpath does not contain the same library version, deserialization fails with <code>ClassNotFoundException</code> or <code>InvalidClassException</code>. That is why the labs provide a leak of dependencies or a signed cookie that reveals the stack.</p><p>The exploit is not &quot;Java is insecure&quot;; it is &quot;the application deserializes untrusted input with a classpath full of useful gadgets&quot;.</p></details><h2 id="phar-and-file-operation-deserialization" tabindex="-1">PHAR and file-operation deserialization <a class="header-anchor" href="#phar-and-file-operation-deserialization" aria-label="Permalink to &quot;PHAR and file-operation deserialization&quot;">​</a></h2><p>PHP&#39;s <code>phar://</code> wrapper deserializes archive metadata when a file function touches a PHAR. Uploading a PHAR and then triggering a file operation (<code>file_exists</code>, <code>getimagesize</code>) can execute a gadget chain without an explicit <code>unserialize</code> call.</p>',3)),a(i,{ids:"deserialization-lab-deserialization-using-phar-deserialization-to-deploy-a-custom-gadget-chain"}),e[5]||(e[5]=t('<details class="details custom-block"><summary>⚙️ Engine Variations: dangerous defaults</summary><ul><li><strong>Java:</strong> <code>ObjectInputStream</code> on untrusted data is the classic sink; <code>readObject</code> runs before validation.</li><li><strong>PHP:</strong> <code>unserialize()</code> with <code>allowed_classes</code> unset accepts any class; <code>__wakeup</code> runs immediately.</li><li><strong>Python:</strong> <code>pickle.loads</code> is equivalent to arbitrary code execution by design; <code>yaml.load</code> without <code>SafeLoader</code> is similar.</li><li><strong>Ruby:</strong> <code>Marshal.load</code> instantiates arbitrary classes; <code>YAML.load</code> historically did too.</li><li><strong>.NET:</strong> <code>BinaryFormatter</code> is deprecated for exactly this reason; <code>TypeNameHandling.All</code> in JSON.NET is a known sink.</li></ul><p>Serializers that support polymorphism are the dangerous ones; data-only formats (JSON with a strict schema) are not.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Never deserialize untrusted data with a format that can instantiate arbitrary classes. Use data-only formats with explicit schemas. If native serialization is unavoidable, sign the payload, encrypt it, and verify integrity before deserialization; restrict allowed classes; run deserialization in a sandbox with no filesystem or network access. Treat <code>phar://</code> as a deserialization sink.</p></div>',2)),a(n,{"topic-id":"insecure-deserialization",label:"Mark deserialization complete"})])}const f=d(p,[["render",u]]);export{z as __pageData,f as default};
